        for (int j = 0; j < size * halfH2; j++) {
            int rowIdx = j / size + halfH, colIdx = j % size;
            if (subsetMask & (1 << j))
                probProduct = (probProduct * ((LLI) matrix[rowIdx][colIdx] * inv100) % MOD) % MOD;
            else
                probProduct = (probProduct * ((LLI) (100 - matrix[rowIdx][colIdx]) * inv100) % MOD) % MOD;
        }
        int possibleStates = 0;
        for (size_t j = 0; j < maskH.size(); j++) {
            vi v;
